// The HTTP Request and XML nodes between 'Split Order Items' and here replace
// item.json with their own output, so we read the original order fields back
// from 'Split Order Items'. With 'Include Other Fields' on, that node nests the
// split product/qty under an 'items' key rather than flattening to root - handle
// both shapes defensively rather than assuming one. Works for both the IMAP and
// webhook triggers, since both feed into 'Split Order Items'.
const raw = $('Split Order Items').item.json;
const original = raw.items && typeof raw.items === 'object' ? raw.items : raw;

// This n8n instance's XML node outputs plain nested objects (confirmed via test
// execution), not xml2js-style arrays - no [0] indexing needed.
const stockValueRaw = item.json?.ENVELOPE?.BODY?.DATA?.STOCKITEM?.CLOSINGBALANCE || "0";

const stockQty = parseFloat(String(stockValueRaw).trim()) || 0;
const qtyOrdered = original.qtyOrdered || 0;
const shortfall = qtyOrdered - stockQty;

return {
  json: {
    orderNumber: raw.orderNumber || original.orderNumber,
    product: original.product,
    qtyOrdered,
    stockQty,
    shortfall: shortfall > 0 ? shortfall : 0,
    fulfilledFromStock: shortfall > 0 ? qtyOrdered - shortfall : qtyOrdered
  }
};

// The 'Compute Shortfall' node ran once, further back - grab its output
// so we know how much shortfall we're multiplying against.
const shortfallData = $('Compute Shortfall1').first().json;
const shortfall = shortfallData.shortfall;

// $input.all() here is every BOM row Google Sheets returned for this item.
const results = $input.all().map(row => ({
  json: {
    orderNumber: shortfallData.orderNumber,
    rawMaterialName: row.json['Raw Material Name'],
    qtyNeeded: parseFloat(row.json['Qty Per Unit']) * shortfall,
    isSelfProduced: String(row.json['Is Self-Produced']).toUpperCase() === 'TRUE'
  }
}));

return results;

// $('When Called by Order Processing').first().json gives us access to the
// original inputs (itemName, qtyNeeded) from further back in this workflow,
// since the XML/HTTP nodes in between don't carry them forward automatically.
const trigger = $('When Called by Order Processing').first().json;

// This n8n instance's XML node outputs plain nested objects (confirmed via test
// execution), not xml2js-style arrays - no [0] indexing needed.
const stockValueRaw = item.json?.ENVELOPE?.BODY?.DATA?.STOCKITEM?.CLOSINGBALANCE || "0";
const stockQty = parseFloat(String(stockValueRaw).trim()) || 0;

const qtyNeeded = trigger.qtyNeeded || 0;
const shortfall = qtyNeeded - stockQty;

return {
  json: {
    itemName: trigger.itemName,
    orderNumber: trigger.orderNumber,
    qtyNeeded,
    stockQty,
    shortfall: shortfall > 0 ? shortfall : 0
  }
};

// $today gives today's date as an n8n Luxon DateTime, in the workflow's timezone.
// We compare just the calendar date (not time) against each row's Timestamp.
const todayStr = $today.toFormat('yyyy-MM-dd');

const todaysRows = $input.all().filter(item => {
  const rowDate = (item.json['Timestamp'] || '').slice(0, 10);
  return rowDate === todayStr;
});

// The two JSON columns were stored as text via JSON.stringify when written,
// so we parse them back into real arrays/objects here.
const parsed = todaysRows.map(item => ({
  json: {
    ...item.json,
    rawMaterialsToPurchase: JSON.parse(item.json['Raw Materials To Buy (JSON)'] || '[]'),
    itemsToManufacture: JSON.parse(item.json['Items To Manufacture (JSON)'] || '[]')
  }
}));

return parsed;

const rows = $input.all().map(i => i.json);

// Set() gives us each distinct order number, so counting its size tells us
// how many separate orders came in today (since one order can span several rows).
const orderNumbers = new Set(rows.map(r => r['Order Number']));

// Combine every row's raw-materials-to-buy list into one flat list.
const allRawMaterials = rows.flatMap(r => r.rawMaterialsToPurchase);
const allItemsToManufacture = rows.flatMap(r => r.itemsToManufacture);

const totalStockUsed = rows.reduce(
  (sum, r) => sum + (parseFloat(r['Stock Used']) || 0),
  0
);

return {
  json: {
    reportDate: $today.toFormat('yyyy-MM-dd'),
    orderCount: orderNumbers.size,
    orders: rows,
    rawMaterialsToPurchase: allRawMaterials,
    itemsToManufacture: allItemsToManufacture,
    totalStockUsed
  }
};

const report = $input.first().json;

return report.orders.map(order => ({
  json: {
    'Order Number': order['Order Number'],
    'Product': order['Product'],
    'Qty Ordered': order['Qty Ordered'],
    'Stock Used': order['Stock Used'],
    'Raw Materials To Buy': JSON.stringify(order.rawMaterialsToPurchase),
    'Items To Manufacture': JSON.stringify(order.itemsToManufacture)
  }
}));

// 'Call BOM Explode' only returns {rawMaterialsToPurchase, itemsToManufacture} from the
// subworkflow - the per-order context from earlier (orderNumber, product, qtyOrdered,
// stockQty, shortfall) doesn't survive the subworkflow call boundary, so we re-attach it
// from 'Compute Shortfall' here.
const original = $('Compute Shortfall').item.json;
return {
  json: {
    ...original,
    rawMaterialsToPurchase: item.json.rawMaterialsToPurchase || [],
    itemsToManufacture: item.json.itemsToManufacture || []
  }
};

// Flattens every raw-material-loop iteration's {rawMaterialsToPurchase, itemsToManufacture}
// into one combined pair of lists to hand back to whoever called this workflow.
const items = $input.all().map(i => i.json);
const rawMaterialsToPurchase = items.flatMap(i => i.rawMaterialsToPurchase || []);
const itemsToManufacture = items.flatMap(i => i.itemsToManufacture || []);
return { json: { rawMaterialsToPurchase, itemsToManufacture } };

// This raw material isn't self-produced, so it's a leaf node - goes straight on the
// purchase list. Shaped to match what the self-produced branch returns, so both sides
// of 'Merge Recursion Branches' are consistent before aggregation.
return {
  json: {
    rawMaterialsToPurchase: [{ name: item.json.rawMaterialName, qty: item.json.qtyNeeded }],
    itemsToManufacture: []
  }
};

// Adds this self-produced raw material's own name/qty into itemsToManufacture before
// merging with whatever the recursive call found further down the BOM tree - otherwise
// the final report only ever shows leaf-level purchases, never the 'make N of X' rows.
const original = $('Calculate Raw Material Needs').item.json;
const nested = item.json;
return {
  json: {
    rawMaterialsToPurchase: nested.rawMaterialsToPurchase || [],
    itemsToManufacture: [
      { name: original.rawMaterialName, qty: original.qtyNeeded },
      ...(nested.itemsToManufacture || [])
    ]
  }
};

// Normalizes the website's webhook payload into the same shape 'Extract Order Table'
// produces from the email path, so both triggers feed 'Split Order Items' identically.
const body = item.json.body || item.json;
return {
  json: {
    orderNumber: body.orderNumber,
    items: (body.items || []).map(i => ({ product: i.product, qtyOrdered: Number(i.qtyOrdered) }))
  }
};

// Best-effort standard Tally HTTP XML 'Export Data' request for a single stock item's
// closing balance. NOT yet verified against a real Tally instance - confirm the report
// name, static variables, and response shape against a real test query before trusting
// this in production (see Compute Shortfall's CLOSINGBALANCE path too).
const companyName = "REPLACE_WITH_YOUR_TALLY_COMPANY_NAME";
const itemName = item.json.product;

const tallyXmlQuery = `<ENVELOPE>
 <HEADER>
  <TALLYREQUEST>Export Data</TALLYREQUEST>
 </HEADER>
 <BODY>
  <EXPORTDATA>
   <REQUESTDESC>
    <REPORTNAME>Stock Summary</REPORTNAME>
    <STATICVARIABLES>
     <SVCURRENTCOMPANY>${companyName}</SVCURRENTCOMPANY>
     <SVSTOCKITEM>${itemName}</SVSTOCKITEM>
    </STATICVARIABLES>
   </REQUESTDESC>
  </EXPORTDATA>
 </BODY>
</ENVELOPE>`;

return { json: { ...item.json, tallyXmlQuery } };

// Builds the HTML body text for the report email using the aggregated numbers from
// 'Aggregate Report Data'.
const report = item.json;

const rows = (report.orders || []).map(o => `
  <tr>
    <td>${o['Order Number']}</td>
    <td>${o['Product']}</td>
    <td>${o['Qty Ordered']}</td>
    <td>${o['Stock Used']}</td>
  </tr>`).join('');

const purchaseItems = (report.rawMaterialsToPurchase || []).map(m => `<li>${m.name}: ${m.qty}</li>`).join('') || '<li>None</li>';
const manufactureItems = (report.itemsToManufacture || []).map(m => `<li>${m.name}: ${m.qty}</li>`).join('') || '<li>None</li>';

const emailHtml = `
<h2>Daily Order Report - ${report.reportDate}</h2>
<p><strong>${report.orderCount}</strong> orders today, <strong>${report.totalStockUsed}</strong> units fulfilled from stock.</p>
<h3>Orders</h3>
<table border="1" cellpadding="6" cellspacing="0">
  <tr><th>Order #</th><th>Product</th><th>Qty Ordered</th><th>Stock Used</th></tr>
  ${rows}
</table>
<h3>Raw Materials To Purchase</h3>
<ul>${purchaseItems}</ul>
<h3>Items To Manufacture</h3>
<ul>${manufactureItems}</ul>
`;

return { json: { emailHtml } };
